import { IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';

/**
 * Invoke an optional renderer hook from the shared options object.
 * @param {string} name
 * @param {*} a
 * @param {*} b
 */
export function invokeRendererHook(name, a, b) {
	let hook;
	if (name === '_diff') hook = options._diff;
	else if (name === '_render') hook = options._render;
	else if (name === '_commit') hook = options._commit;
	else if (name === 'diffed') hook = options.diffed;
	else if (name === 'unmount') hook = options.unmount;
	else if (name === '_root') hook = options._root;
	else hook = options[name];
	if (hook) return hook(a, b);
}

/**
 * Forward a render-time exception to the configured error hook.
 * @param {*} error
 * @param {import('../internal').VNode} vnode
 * @param {import('../internal').VNode} [oldVNode]
 */
export function reportRendererError(error, vnode, oldVNode) {
	options._catchError(error, vnode, oldVNode);
}

/**
 * Apply the optional event transform used by addons.
 * @param {Event} e
 */
export function transformEvent(e) {
	return options.event ? options.event(e) : e;
}

/**
 * Set a style property on a DOM node
 * @param {object} style
 * @param {string} key
 * @param {*} value
 */
export function setStyle(style, key, value) {
	if (key[0] === '-') {
		style.setProperty(key, value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
}

/**
